import React, { useCallback, useContext, useEffect, useState } from "react";
import MainLayout from "../layouts/MainLayout";
import { supabase } from "../utils/supabase";
import { SessionContext } from "../contexts/SessionContext";
import { useNavigate } from "react-router-dom";
import {
	FiSearch,
	FiUsers,
	FiShield,
	FiSave,
	FiRefreshCw,
	FiTrash2,
	FiRotateCcw,
	FiPlus,
} from "react-icons/fi";
import DOMPurify from "dompurify";
import { isGmailAddress } from "../utils/contact-validation";
import { getAccountDisplayName, normalizeAccountRole } from "../utils/account-profile";

const getInitials = (name) => {
	const parts = String(name || "")
		.trim()
		.split(/\s+/)
		.filter(Boolean);

	if (parts.length === 0) return "?";
	if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();

	return `${parts[0][0]}${parts[parts.length - 1][0]}`.toUpperCase();
};

const getDisplayName = getAccountDisplayName;
const normalizeRole = normalizeAccountRole;

const ManageClients = () => {
	const { session, profile } = useContext(SessionContext);
	const navigate = useNavigate();
	const [profiles, setProfiles] = useState([]);
	const [loading, setLoading] = useState(true);
	const [searchTerm, setSearchTerm] = useState("");
	const [roleFilter, setRoleFilter] = useState("client");
	const [statusFilter, setStatusFilter] = useState("active");
	const [selectedProfileId, setSelectedProfileId] = useState("");
	const [saving, setSaving] = useState(false);
	const [deleting, setDeleting] = useState(false);
	const [creating, setCreating] = useState(false);
	const [showCreateForm, setShowCreateForm] = useState(false);
	const [status, setStatus] = useState("");
	const [createForm, setCreateForm] = useState({ firstname: "", lastname: "", email: "", password: "", role: "staff" });
	const [form, setForm] = useState({
		firstname: "",
		lastname: "",
		email: "",
		role: "staff",
	});

	useEffect(() => {
		if (!session) {
			navigate("/log-in");
			return;
		}

		if (profile && profile.role !== "admin") {
			navigate("/");
		}
	}, [session, profile, navigate]);

	const refreshProfiles = useCallback(async () => {
		setLoading(true);
		const { data, error } = await supabase
			.from("profiles")
			.select("id, firstname, lastname, email, avatar_url, role, deleted_at, created_at")
			.order("created_at", { ascending: false });

		if (error) {
			setLoading(false);
			alert(error.message || error);
			return;
		}

		const nextProfiles = (data || []).slice().sort((left, right) => {
			const leftName = getDisplayName(left).toLowerCase();
			const rightName = getDisplayName(right).toLowerCase();

			return leftName.localeCompare(rightName);
		});

		setProfiles(nextProfiles);
		setLoading(false);

		if (nextProfiles.length > 0) {
			setSelectedProfileId((current) => current || nextProfiles[0].id);
		}
	}, []);

	const updateProfileCache = (updatedProfile) => {
		setProfiles((current) =>
			current
				.map((entry) =>
					entry.id === updatedProfile.id
						? { ...entry, ...updatedProfile }
						: entry,
				)
				.slice()
				.sort((left, right) =>
					getDisplayName(left)
						.toLowerCase()
						.localeCompare(getDisplayName(right).toLowerCase()),
				),
		);
	};

	useEffect(() => {
		if (profile?.role !== "admin") return;
		void refreshProfiles();

		// Real-time listener para sa anumang pagbabago sa profiles table
		const channel = supabase
			.channel("manage-clients-realtime")
			.on(
				"postgres_changes",
				{ event: "UPDATE", schema: "public", table: "profiles" },
				(payload) => {
					updateProfileCache(payload.new);
				}
			)
			.subscribe();

		return () => {
			supabase.removeChannel(channel);
		};
	}, [profile?.role, refreshProfiles]);

	const selectedProfile =
		profiles.find((entry) => entry.id === selectedProfileId) || null;
	const selectedIsDeleted = Boolean(selectedProfile?.deleted_at);
	const canDeleteSelected = Boolean(
		selectedProfile && selectedProfile.role !== "admin",
	);

	const selectProfile = (entry) => {
		setSelectedProfileId(entry.id);
		setStatus("");
		setForm({
			firstname: entry.firstname || "",
			lastname: entry.lastname || "",
			email: entry.email || "",
			role: normalizeRole(entry.role),
		});
	};

	const filteredProfiles = profiles.filter((entry) => {
		const matchesSearch =
			`${entry.firstname || ""} ${entry.lastname || ""} ${entry.email || ""}`
				.toLowerCase()
				.includes(searchTerm.toLowerCase().trim());
		const matchesRole =
			roleFilter === "all" ? true : normalizeRole(entry.role) === roleFilter;
		const matchesStatus =
			statusFilter === "all"
				? true
				: statusFilter === "deleted"
					? Boolean(entry.deleted_at)
					: !entry.deleted_at;

		return matchesSearch && matchesRole && matchesStatus;
	});

	const handleSave = async (event) => {
		event.preventDefault();

		if (!selectedProfile) return;
		if (!isGmailAddress(form.email)) {
			setStatus("Account email must end in @gmail.com.");
			return;
		}

		setSaving(true);
		setStatus("");

		const { data, error } = await supabase
			.from("profiles")
			.update({
				firstname: DOMPurify.sanitize(form.firstname.trim()),
				lastname: DOMPurify.sanitize(form.lastname.trim()),
				email: DOMPurify.sanitize(form.email.trim().toLowerCase()),
				role: form.role,
			})
			.eq("id", selectedProfile.id)
			.select()
			.single();

		if (error) {
			setSaving(false);
			alert(error.message || error);
			return;
		}

		setStatus(
			`${getDisplayName(data)} updated successfully. This account is now a ${
				{ admin: "administrator", staff: "staff member", client: "client" }[normalizeRole(data.role)]
			}.`,
		);
		setForm({
			firstname: data.firstname || "",
			lastname: data.lastname || "",
			email: data.email || "",
			role: normalizeRole(data.role),
		});
		setProfiles((current) =>
			current
				.map((entry) =>
					entry.id === data.id
						? {
								...entry,
								...data,
						  }
						: entry,
				)
				.slice()
				.sort((left, right) =>
					getDisplayName(left).toLowerCase().localeCompare(getDisplayName(right).toLowerCase()),
				),
		);
		setSaving(false);
	};

	const handleReset = () => {
		if (!selectedProfile) return;

		setForm({
			firstname: selectedProfile.firstname || "",
			lastname: selectedProfile.lastname || "",
			email: selectedProfile.email || "",
			role: normalizeRole(selectedProfile.role),
		});
		setStatus("");
	};

	const handleCreate = async (event) => {
		event.preventDefault();
		if (!isGmailAddress(createForm.email)) {
			setStatus("New accounts must use an email ending in @gmail.com.");
			return;
		}
		setCreating(true);
		setStatus("");

		try {
			const { data: sessionData, error: sessionError } = await supabase.auth.getSession();
			const accessToken = sessionData.session?.access_token;
			if (sessionError || !accessToken) {
				throw new Error("Your session expired. Please log in again.");
			}

			const response = await fetch("/api/admin-create-account", {
				method: "POST",
				headers: { "Content-Type": "application/json", Authorization: `Bearer ${accessToken}` },
				body: JSON.stringify({
					...createForm,
					firstname: DOMPurify.sanitize(createForm.firstname.trim()),
					lastname: DOMPurify.sanitize(createForm.lastname.trim()),
					email: createForm.email.trim().toLowerCase(),
				}),
			});
			const responseText = await response.text();
			let result;
			try {
				result = JSON.parse(responseText);
			} catch {
				throw new Error(
					response.ok
						? "The server returned an invalid response."
						: `Account creation endpoint unavailable (${response.status}). Run this through Vercel, not Vite alone.`,
				);
			}
			if (!response.ok) throw new Error(result.error || "Unable to create the account.");

			setProfiles((current) => [result.profile, ...current]);
			setSelectedProfileId(result.profile.id);
			setCreateForm({ firstname: "", lastname: "", email: "", password: "", role: "staff" });
			setShowCreateForm(false);
			setStatus(`${getDisplayName(result.profile)} was created successfully.`);
		} catch (error) {
			setStatus(error.message || "Unable to create the account.");
		} finally {
			setCreating(false);
		}
	};

	const handleDeleteToggle = async () => {
		if (!selectedProfile || selectedProfile.role === "admin") return;

		const isCurrentlyDeleted = Boolean(selectedProfile.deleted_at);
		const action = isCurrentlyDeleted ? "restore" : "delete";
		const confirmMessage = isCurrentlyDeleted
			? `Restore ${getDisplayName(selectedProfile)}?`
			: `Delete ${getDisplayName(selectedProfile)}? This will hide the account from active use, but it can still be restored.`;

		if (!window.confirm(confirmMessage)) return;

		setDeleting(true);
		setStatus("");

		const { data, error } = await supabase
			.from("profiles")
			.update({
				deleted_at: isCurrentlyDeleted ? null : new Date().toISOString(),
			})
			.eq("id", selectedProfile.id)
			.select("id, firstname, lastname, email, avatar_url, role, deleted_at, created_at")
			.single();

		if (error) {
			setDeleting(false);
			alert(error.message || error);
			return;
		}

		updateProfileCache(data);
		setSelectedProfileId(data.id);
		setForm({
			firstname: data.firstname || "",
			lastname: data.lastname || "",
			email: data.email || "",
			role: normalizeRole(data.role),
		});
		setStatus(
			`${getDisplayName(data)} ${action}d successfully. ${
				action === "delete" ? "You can restore it from the deleted list." : "The account is active again."
			}`,
		);
		setStatusFilter(isCurrentlyDeleted ? "active" : "deleted");
		setDeleting(false);
	};

	return (
		<MainLayout>
			<div className="min-h-[calc(100vh-4rem)] w-full min-w-0 overflow-x-hidden bg-[linear-gradient(180deg,_#fffaf0_0%,_#fff4e3_45%,_#f9ead3_100%)] px-3 py-5 sm:px-6 sm:py-8 lg:px-8">
				<div className="mx-auto w-full max-w-7xl min-w-0 space-y-5 sm:space-y-6">
					<div className="rounded-[1.5rem] border border-black/5 bg-white/80 p-5 shadow-2xl backdrop-blur sm:rounded-[2rem] sm:p-6 md:p-8">
						<div className="flex flex-col gap-4 md:flex-row md:items-end md:justify-between">
							<div className="max-w-3xl">
								<p className="text-sm font-medium uppercase tracking-[0.18em] text-base-content/55">
									Admin Dashboard
								</p>
								<h1 className="mt-3 break-words text-3xl font-black tracking-tight text-base-content md:text-4xl">
									Manage Clients
								</h1>
								<p className="mt-3 max-w-2xl text-sm leading-6 text-base-content/70 md:text-base">
									Search accounts, update profile details, and manage account access.
								</p>
							</div>
							<div className="flex flex-wrap items-center gap-2 sm:gap-3">
								<div className="inline-flex items-center gap-2 rounded-full bg-base-200 px-3 py-2 text-sm font-medium text-base-content/70 sm:px-4">
									<FiUsers />
									<span>{profiles.filter((entry) => normalizeRole(entry.role) === "client").length} clients</span>
								</div>
								<div className="inline-flex items-center gap-2 rounded-full bg-base-200 px-3 py-2 text-sm font-medium text-base-content/70 sm:px-4">
									<FiUsers />
									<span>{profiles.filter((entry) => normalizeRole(entry.role) === "staff").length} staff</span>
								</div>
								<div className="inline-flex items-center gap-2 rounded-full bg-base-200 px-3 py-2 text-sm font-medium text-base-content/70 sm:px-4">
									<FiShield />
									<span>{profiles.filter((entry) => entry.role === "admin").length} admins</span>
								</div>
								<button
									type="button"
									onClick={refreshProfiles}
									className="btn btn-outline btn-sm rounded-full sm:btn-md"
								>
									<FiRefreshCw />
									Refresh
								</button>
								<button type="button" onClick={() => { setShowCreateForm(true); setStatus(""); }} className="btn btn-black btn-sm rounded-full sm:btn-md">
									<FiPlus />
									Add account
								</button>
								<button onClick={() => navigate(-1)} className="btn btn-black btn-sm rounded-full sm:btn-md">
									Back
								</button>
							</div>
						</div>
					</div>

					<div className="grid w-full min-w-0 grid-cols-1 gap-4 sm:gap-6 lg:grid-cols-[0.95fr_1.05fr]">
						<div className="w-full min-w-0 rounded-[1.5rem] border border-black/5 bg-white/85 p-4 shadow-xl backdrop-blur sm:rounded-[2rem] sm:p-6">
							<div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
								<div>
									<h2 className="text-xl font-bold text-base-content">Accounts</h2>
									<p className="text-sm text-base-content/60">
										Search and pick the account you want to edit.
									</p>
								</div>
								<div className="flex w-full flex-col gap-3 sm:w-auto sm:flex-row">
									<select
										className="select select-bordered select-sm w-full sm:w-36"
										value={roleFilter}
										onChange={(event) => setRoleFilter(event.target.value)}
									>
										<option value="client">Clients</option>
										<option value="staff">Staff</option>
										<option value="admin">Admins</option>
										<option value="all">All Roles</option>
									</select>
									<select
										className="select select-bordered select-sm w-full sm:w-40"
										value={statusFilter}
										onChange={(event) => setStatusFilter(event.target.value)}
									>
										<option value="active">Active</option>
										<option value="deleted">Deleted</option>
										<option value="all">All Status</option>
									</select>
								</div>
							</div>

							<label className="mt-5 flex items-center gap-3 rounded-2xl border border-base-300 bg-base-100 px-4 py-3">
								<FiSearch className="text-base-content/55" />
								<input
									type="text"
									value={searchTerm}
									onChange={(event) => setSearchTerm(event.target.value)}
									placeholder="Search by name or email"
									className="w-full bg-transparent outline-none placeholder:text-base-content/35"
								/>
							</label>

							<div className="mt-5 space-y-3">
								{loading && (
									<div className="rounded-2xl border border-dashed border-base-300 p-6 text-center text-sm text-base-content/60">
										Loading accounts...
									</div>
								)}

								{!loading && filteredProfiles.length === 0 && (
									<div className="rounded-2xl border border-dashed border-base-300 p-6 text-center text-sm text-base-content/60">
										No accounts match your filters.
									</div>
								)}

								{filteredProfiles.map((entry) => {
									const isSelected = entry.id === selectedProfileId;
									const avatarAlt = getDisplayName(entry);

									return (
										<button
											key={entry.id}
											type="button"
											onClick={() => selectProfile(entry)}
											className={[
												"flex w-full min-w-0 items-center gap-3 rounded-2xl border p-3 text-left transition sm:gap-4 sm:p-4",
												isSelected
													? "border-black bg-black text-white shadow-lg"
													: "border-base-300 bg-base-100 hover:border-base-content/25 hover:bg-base-200",
											].join(" ")}
										>
											<div className="flex h-12 w-12 shrink-0 items-center justify-center overflow-hidden rounded-full bg-gradient-to-br from-amber-200 to-orange-300 text-sm font-bold text-slate-800 sm:h-14 sm:w-14">
												{entry.avatar_url ? (
													<img
														src={entry.avatar_url}
														alt={avatarAlt}
														className="h-full w-full object-cover"
													/>
												) : (
													getInitials(avatarAlt)
												)}
											</div>
											<div className="min-w-0 flex-1">
												<div className="flex min-w-0 items-center justify-between gap-2">
													<p className="min-w-0 truncate text-sm font-semibold sm:text-base">
														{avatarAlt}
													</p>
													<span
														className={[
															"badge badge-sm border-0",
															normalizeRole(entry.role) === "admin"
																? "bg-emerald-500 text-white"
																: "bg-amber-400 text-slate-900",
														].join(" ")}
													>
														{normalizeRole(entry.role)}
													</span>
												</div>
												<p
													className={[
														"truncate text-sm",
														isSelected ? "text-white/75" : "text-base-content/60",
													].join(" ")}
												>
													{entry.email || "No email on file"}
												</p>
											</div>
										</button>
									);
								})}
							</div>
						</div>

						<div className="min-w-0 rounded-[1.5rem] border border-black/5 bg-white/85 p-4 shadow-xl backdrop-blur sm:rounded-[2rem] sm:p-6">
							{showCreateForm ? (
								<form onSubmit={handleCreate} className="space-y-6">
									<div className="border-b border-base-200 pb-5">
										<p className="text-xs font-semibold uppercase tracking-[0.22em] text-base-content/45">New account</p>
										<h2 className="mt-2 text-2xl font-black text-base-content">Add staff or admin</h2>
										<p className="mt-2 text-sm text-base-content/60">The account can sign in immediately using the password you provide.</p>
									</div>
									<div className="grid gap-5 md:grid-cols-2">
										{["firstname", "lastname"].map((field) => (
											<label key={field} className="form-control"><div className="label"><span className="label-text font-medium">{field === "firstname" ? "First name" : "Last name"}</span></div><input required type="text" value={createForm[field]} onChange={(event) => setCreateForm((current) => ({ ...current, [field]: event.target.value }))} className="input input-bordered w-full" /></label>
										))}
									</div>
									<label className="form-control"><div className="label"><span className="label-text font-medium">Email (@gmail.com only)</span></div><input required type="email" value={createForm.email} onChange={(event) => setCreateForm((current) => ({ ...current, email: event.target.value }))} className="input input-bordered w-full" placeholder="you@gmail.com" /></label>
									<div className="grid gap-5 md:grid-cols-2">
										<label className="form-control"><div className="label"><span className="label-text font-medium">Temporary password</span></div><input required minLength={8} type="password" value={createForm.password} onChange={(event) => setCreateForm((current) => ({ ...current, password: event.target.value }))} className="input input-bordered w-full" /></label>
										<label className="form-control"><div className="label"><span className="label-text font-medium">Account role</span></div><select className="select select-bordered w-full" value={createForm.role} onChange={(event) => setCreateForm((current) => ({ ...current, role: event.target.value }))}><option value="client">Client</option><option value="staff">Staff</option><option value="admin">Admin</option></select></label>
									</div>
									<div className="flex flex-wrap gap-3 pt-2"><button type="submit" disabled={creating} className="btn btn-black rounded-full px-6"><FiPlus />{creating ? "Creating..." : "Create account"}</button><button type="button" onClick={() => setShowCreateForm(false)} className="btn btn-outline rounded-full px-6">Cancel</button></div>
								</form>
							) : selectedProfile ? (
								<form onSubmit={handleSave} className="space-y-4 sm:space-y-6">
									<div className="flex items-start justify-between gap-3 border-b border-base-200 pb-4 sm:gap-4 sm:pb-5">
										<div className="min-w-0">
											<p className="text-xs font-semibold uppercase tracking-[0.22em] text-base-content/45">
												Selected account
											</p>
											<h2 className="mt-2 break-words text-xl font-black text-base-content sm:text-2xl">
												{getDisplayName(selectedProfile)}
											</h2>
											<p className="mt-2 text-sm text-base-content/60">
												Edit the profile fields below and save the changes.
											</p>
										</div>
										<span
											className={[
											"badge badge-md shrink-0 border-0 px-3 py-2 sm:badge-lg sm:px-4 sm:py-3",
												form.role === "admin"
													? "bg-emerald-500 text-white"
													: "bg-amber-400 text-slate-900",
											].join(" ")}
										>
											{form.role}
										</span>
									</div>

									<div className="flex min-w-0 items-center gap-3 rounded-2xl border border-base-300 bg-base-100 p-3 sm:gap-4 sm:rounded-3xl sm:p-4">
										<div className="flex h-14 w-14 shrink-0 items-center justify-center overflow-hidden rounded-full bg-gradient-to-br from-amber-200 to-orange-300 text-lg font-bold text-slate-800 sm:h-20 sm:w-20 sm:text-xl">
											{selectedProfile.avatar_url ? (
												<img
													src={selectedProfile.avatar_url}
													alt={getDisplayName(selectedProfile)}
													className="h-full w-full object-cover"
												/>
											) : (
												getInitials(getDisplayName(selectedProfile))
											)}
										</div>
										<div className="min-w-0">
										<p className="text-xs font-semibold uppercase tracking-[0.16em] text-base-content/50 sm:text-sm">
											{normalizeRole(selectedProfile.role) === "admin" ? "Administrator" : normalizeRole(selectedProfile.role) === "staff" ? "Staff account" : "Client account"}
										</p>
										<p className="mt-1 break-all text-sm text-base-content/65">
												{selectedProfile.email || "No email on file"}
											</p>
											{selectedIsDeleted && (
												<p className="mt-2 inline-flex rounded-full bg-rose-100 px-3 py-1 text-xs font-semibold text-rose-700">
													Deleted account
												</p>
											)}
										</div>
									</div>

									<div className="grid gap-5 md:grid-cols-2">
										<label className="form-control">
											<div className="label">
												<span className="label-text font-medium">First name</span>
											</div>
											<input
												type="text"
												value={form.firstname}
												onChange={(event) =>
													setForm((current) => ({
														...current,
														firstname: event.target.value,
													}))
												}
												className="input input-bordered w-full"
												placeholder="Enter first name"
											/>
										</label>

										<label className="form-control">
											<div className="label">
												<span className="label-text font-medium">Last name</span>
											</div>
											<input
												type="text"
												value={form.lastname}
												onChange={(event) =>
													setForm((current) => ({
														...current,
														lastname: event.target.value,
													}))
												}
												className="input input-bordered w-full"
												placeholder="Enter last name"
											/>
										</label>
									</div>

									<label className="form-control">
										<div className="label">
											<span className="label-text font-medium">Email</span>
										</div>
										<input
											type="email"
											value={form.email}
											onChange={(event) =>
												setForm((current) => ({
													...current,
													email: event.target.value,
												}))
											}
											className="input input-bordered w-full"
											placeholder="you@gmail.com"
										/>
									</label>

									<label className="form-control">
										<div className="label">
											<span className="label-text font-medium">Account role</span>
										</div>
										<select
											className="select select-bordered w-full"
											value={form.role}
											onChange={(event) =>
												setForm((current) => ({
													...current,
													role: event.target.value,
												}))
											}
										>
											<option value="client">Client</option>
											<option value="staff">Staff</option>
											<option value="admin">Admin</option>
										</select>
									</label>

									<div className="rounded-2xl bg-base-200 px-4 py-4 text-sm leading-6 text-base-content/70">
										Administrators can change account roles to client, staff, or admin.
									</div>

									{status && (
										<div className="rounded-2xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm text-emerald-700">
											{status}
										</div>
									)}
									<div className="flex flex-col gap-2 pt-2 sm:flex-row sm:flex-wrap sm:gap-3">
										<button
											type="submit"
											disabled={saving}
											className="btn btn-black w-full rounded-full px-5 sm:w-auto sm:px-6"
										>
											<FiSave />
											{saving ? "Saving..." : "Save changes"}
										</button>
										<button
											type="button"
											onClick={handleReset}
											className="btn btn-outline w-full rounded-full px-5 sm:w-auto sm:px-6"
										>
											Reset form
										</button>
										{canDeleteSelected && (
											<button
												type="button"
												onClick={handleDeleteToggle}
												disabled={deleting}
												className={[
											"btn w-full rounded-full px-5 sm:w-auto sm:px-6",
													selectedIsDeleted ? "btn-success" : "btn-error",
												].join(" ")}
											>
												{selectedIsDeleted ? <FiRotateCcw /> : <FiTrash2 />}
												{deleting
													? "Working..."
													: selectedIsDeleted
														? "Restore account"
														: "Delete account"}
											</button>
										)}
									</div>
								</form>
							) : (
								<div className="flex min-h-[28rem] items-center justify-center rounded-[1.5rem] border border-dashed border-base-300 bg-base-100 p-8 text-center">
									<div className="max-w-md">
										<h2 className="text-2xl font-black text-base-content">
											No account selected
										</h2>
										<p className="mt-3 text-sm leading-6 text-base-content/60">
											Pick a staff member from the left pane to inspect their profile and
											adjust their account details.
										</p>
									</div>
								</div>
							)}
						</div>
					</div>
				</div>
			</div>
		</MainLayout>
	);
};

export default ManageClients;
